//! 📬️ One owning image publication admits original fields, mutations and selection before atomic handoff.
use crate::{DrawingImageAsset,DrawingImageBody,DrawingLayerBase,DrawingLayerNode,DrawingMutation,DrawingSnapshot};
use semio_framework_plugin::{AppOperationContext,InteractionWrite};
use semio_framework_value::{paged::{PagedUtf8,PagedUtf8AppendCursor},retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep},RetirementDemand,ValueError,ValueRefusalKind};
type Text=PagedUtf8<{usize::MAX}>;
struct PublicationHash(semio_framework_hash::Sha256);
struct PublicationHashRetirement{value:Option<PublicationHash>}
impl semio_framework_value::retirement::RetireOwned for PublicationHash{
 fn retirement(self)->Box<dyn semio_framework_value::retirement::RetirementCursor>{Box::new(PublicationHashRetirement{value:Some(self)})}
 fn retirement_birth_bytes(&self)->Option<usize>{Some(size_of::<PublicationHashRetirement>())}
 fn controlled_retirement_supported()->bool{true}
}
impl semio_framework_value::retirement::RetirementCursor for PublicationHashRetirement{
 fn close_step(&mut self,grant:RetainedCloneGrant)->semio_framework_value::retirement::RetirementStep{use semio_framework_value::retirement::RetirementStep;if self.value.is_none(){return RetirementStep::Complete;}let copy=size_of::<PublicationHash>();if grant.maximum_items==0||grant.maximum_depth==0||grant.maximum_copy_bytes<copy{return RetirementStep::BudgetExhausted;}self.value=None;RetirementStep::ProcessedBytes(copy)}
 fn terminal_is_empty(&self)->bool{self.value.is_none()}
 fn terminal_release_bytes(&self)->Option<usize>{self.value.is_none().then_some(size_of::<Self>())}
 fn next_work_byte_demand(&self)->Result<usize,ValueError>{Ok(if self.value.is_some(){size_of::<PublicationHash>()}else{0})}
 fn next_close_byte_demand(&self)->Option<usize>{Some(0)}
 fn next_birth_bytes(&self,_body:usize)->Option<usize>{Some(0)}
 fn next_depth_demand(&self)->Result<usize,ValueError>{Ok(usize::from(self.value.is_some()))}
}
#[derive(semio_framework_value::RetireOwned)]
pub(crate) struct DrawingImagePublication{pub mutations:Vec<DrawingMutation>,pub selection:Vec<InteractionWrite>}
#[derive(semio_framework_value::RetireOwned)]
pub(crate) struct DrawingImagePublicationJob{hash:Option<PublicationHash>,seed_offset:usize,asset:Option<DrawingImageAsset>,asset_id:[u8;160],layer_id:[u8;160],asset_length:usize,layer_length:usize,texts:[Text;6],append:[PagedUtf8AppendCursor;6],text:usize,phase:usize,root:usize,path:[usize;128],depth:usize,visited:usize,parent_seen:bool,layer:Option<DrawingLayerNode>,boxed_layer:Option<Box<DrawingLayerNode>>,mutations:Vec<DrawingMutation>,strings:[String;3],string_fill:bool,targets:Vec<protocol::InteractionTarget>,selection:Vec<InteractionWrite>}
fn identity(output:&mut[u8;160],prefix:&[u8],parts:&[&[u8]])->usize{output[..prefix.len()].copy_from_slice(prefix);let mut at=prefix.len();for part in parts{for byte in *part{output[at]=b"0123456789abcdef"[(byte>>4)as usize];output[at+1]=b"0123456789abcdef"[(byte&15)as usize];at+=2;}}at}
fn refused(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn node_at<'a>(snapshot:&'a DrawingSnapshot,root:usize,path:&[usize])->Option<&'a DrawingLayerNode>{let mut node=snapshot.layers.get(root)?;for index in path{let DrawingLayerNode::Group(group)=node else{return None};node=group.children.get(*index)?;}Some(node)}
impl DrawingImagePublicationJob{
 pub(crate) fn new(asset:DrawingImageAsset,operation:&AppOperationContext)->Self{let mut hash=semio_framework_hash::Sha256::new();hash.update(b"semio.draw.image-publication/v1");hash.update(&operation.canonical_base_revision);hash.update(&operation.app_instance_id.to_be_bytes());hash.update(&operation.operation_id.to_be_bytes());hash.update(&operation.generation.to_be_bytes());hash.update(&(operation.authoring_seed.len()as u64).to_be_bytes());Self{hash:Some(PublicationHash(hash)),seed_offset:0,asset:Some(asset),asset_id:[0;160],layer_id:[0;160],asset_length:0,layer_length:0,texts:std::array::from_fn(|_|Default::default()),append:std::array::from_fn(|_|Default::default()),text:0,phase:16,root:0,path:[0;128],depth:0,visited:0,parent_seen:false,layer:None,boxed_layer:None,mutations:Vec::new(),strings:std::array::from_fn(|_|String::new()),string_fill:false,targets:Vec::new(),selection:Vec::new()}}
 fn asset_identity(&self)->&str{std::str::from_utf8(&self.asset_id[..self.asset_length]).unwrap()}
 fn layer_identity(&self)->&str{std::str::from_utf8(&self.layer_id[..self.layer_length]).unwrap()}
 fn text_source<'a>(&'a self,input:&'a super::ImportImage)->&'a str{match self.text{0|1=>self.asset_identity(),2=>self.layer_identity(),3=>input.name.as_deref().filter(|name|!name.is_empty()).unwrap_or("Image"),4=>"normal",_=>input.parent_id.as_deref().unwrap_or("")}}
 fn string_source(&self)->&str{match self.phase{7=>crate::editor::drawing::DRAWING_INTERACTION_DOMAIN,8=>crate::editor::drawing::DRAWING_INTERACTION_GRANULARITY,_=>self.layer_identity()}}
 pub(crate) fn work_demands(&self,input:&super::ImportImage,operation:&AppOperationContext,maximum_copy_bytes:usize)->Result<RetirementDemand,ValueError>{let word=size_of::<usize>();let mut demand=RetirementDemand{depth:1,..Default::default()};match self.phase{16=>demand.copy_bytes=size_of::<PublicationHash>()+operation.authoring_seed.len().saturating_sub(self.seed_offset).min(64)+2*word,17=>demand.copy_bytes=2*size_of::<[u8;160]>()+size_of::<PublicationHash>()+2*word,0=>{let child=self.append[self.text].work_demands(self.text_source(input),&self.texts[self.text],maximum_copy_bytes.saturating_sub(word))?;demand.copy_bytes=child.copy_bytes+word;demand.capacity_bytes=child.capacity_bytes;},1=>demand.copy_bytes=size_of::<[usize;128]>()+5*word,2=>demand.copy_bytes=size_of::<DrawingLayerNode>()+3*size_of::<Text>()+word,3=>{demand.copy_bytes=size_of::<DrawingLayerNode>()+word;demand.capacity_bytes=size_of::<DrawingLayerNode>();},4=>{demand.copy_bytes=size_of::<Vec<DrawingMutation>>()+word;demand.capacity_bytes=2*size_of::<DrawingMutation>();},5|6=>demand.copy_bytes=size_of::<DrawingMutation>()+word,7..=9=>{demand.copy_bytes=if self.string_fill{self.string_source().len()+2*word}else{size_of::<String>()+word};demand.capacity_bytes=if self.string_fill{0}else{self.string_source().len()};},10=>{demand.copy_bytes=size_of::<Vec<protocol::InteractionTarget>>()+word;demand.capacity_bytes=size_of::<protocol::InteractionTarget>();},11=>demand.copy_bytes=size_of::<protocol::InteractionTarget>()+3*size_of::<String>()+word,12=>{demand.copy_bytes=size_of::<Vec<InteractionWrite>>()+word;demand.capacity_bytes=size_of::<InteractionWrite>();},13=>demand.copy_bytes=size_of::<InteractionWrite>()+size_of::<String>()+size_of::<Vec<protocol::InteractionTarget>>()+word,14=>demand.copy_bytes=size_of::<DrawingImagePublication>()+word,_=>return Err(refused("image publication already transferred"))};Ok(demand)}
 pub(crate) fn ready(&self)->bool{self.phase==14}
 pub(crate) fn advance(&mut self,snapshot:&DrawingSnapshot,input:&super::ImportImage,operation:&AppOperationContext,grant:RetainedCloneGrant)->Result<RetainedCloneProgress,ValueError>{let demand=self.work_demands(input,operation,grant.maximum_copy_bytes)?;if grant.maximum_items==0||grant.maximum_depth<demand.depth||grant.maximum_copy_bytes<demand.copy_bytes||grant.maximum_capacity_bytes<demand.capacity_bytes{return Ok(Default::default());}let mut receipt=RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()};match self.phase{
  16=>{let end=(self.seed_offset+64).min(operation.authoring_seed.len());self.hash.as_mut().unwrap().0.update(&operation.authoring_seed.as_bytes()[self.seed_offset..end]);self.seed_offset=end;if end==operation.authoring_seed.len(){self.phase=17;}},
  17=>{let digest=self.hash.take().unwrap().0.finalize();self.asset_length=identity(&mut self.asset_id,b"image-asset-",&[&digest]);self.layer_length=identity(&mut self.layer_id,b"layer-",&[&digest]);self.phase=0;},
  0=>{let text=self.text;let source=match text{0|1=>std::str::from_utf8(&self.asset_id[..self.asset_length]).unwrap(),2=>std::str::from_utf8(&self.layer_id[..self.layer_length]).unwrap(),3=>input.name.as_deref().filter(|name|!name.is_empty()).unwrap_or("Image"),4=>"normal",_=>input.parent_id.as_deref().unwrap_or("")};let child=self.append[text].advance(source,&mut self.texts[text],RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:grant.maximum_copy_bytes-size_of::<usize>(),..grant})?;receipt=child.progress();if receipt.copied_items>0{receipt.copied_bytes+=size_of::<usize>();}if matches!(child,RetainedCloneStep::Complete(_)){self.text+=1;if self.text==6{self.phase=1;}}},
  1=>{if snapshot.assets.get(&self.texts[0]).is_some(){return Err(refused("image asset identity already exists"));}if let Some(node)=node_at(snapshot,self.root,&self.path[..self.depth]){if self.visited>=4096{return Err(refused("image publication source node allowance exceeded"));}if crate::schema::layer_id(node).eq_str(self.layer_identity()){return Err(refused("image layer identity already exists"));}self.visited+=1;if input.parent_id.as_ref().is_some_and(|id|crate::schema::layer_id(node).eq_str(id)){let DrawingLayerNode::Group(group)=node else{return Err(refused("image destination must be a group"));};for depth in 0..=self.depth{if crate::schema::layer_base(node_at(snapshot,self.root,&self.path[..depth]).unwrap()).locked{return Err(refused("image destination inherits a locked layer"));}}if input.index.is_some_and(|index|index>group.children.len()){return Err(refused("image destination index exceeds group extent"));}self.parent_seen=true;}if let DrawingLayerNode::Group(group)=node{if !group.children.is_empty(){if self.depth==128{return Err(refused("image publication source depth allowance exceeded"));}self.path[self.depth]=0;self.depth+=1;return Ok(receipt);}}loop{if self.depth==0{self.root+=1;break;}let at=self.depth-1;self.path[at]+=1;if node_at(snapshot,self.root,&self.path[..self.depth]).is_some(){break;}self.depth-=1;}}else{if input.parent_id.is_some()&&!self.parent_seen{return Err(refused("image destination group is missing"));}if input.parent_id.is_none()&&input.index.is_some_and(|index|index>snapshot.layers.len()){return Err(refused("image destination index exceeds root extent"));}self.phase=2;}},
  2=>{let asset=self.asset.as_ref().unwrap();self.layer=Some(DrawingLayerNode::Image(DrawingImageBody{base:DrawingLayerBase{id:std::mem::take(&mut self.texts[2]),name:std::mem::take(&mut self.texts[3]),visible:true,locked:false,opacity:1.0,blend_mode:std::mem::take(&mut self.texts[4]),transform:crate::default_drawing_transform(),attributes:Default::default()},image_key:std::mem::take(&mut self.texts[1]),width:asset.width as f64,height:asset.height as f64}));self.phase=3;},
  3=>{self.boxed_layer=Some(Box::new(self.layer.take().unwrap()));receipt.retained_capacity_bytes=size_of::<DrawingLayerNode>();self.phase=4;},
  4=>{self.mutations.try_reserve_exact(2).map_err(|_|refused("image mutation backing admission failed"))?;receipt.retained_capacity_bytes=self.mutations.capacity()*size_of::<DrawingMutation>();self.phase=5;},
  5=>{self.mutations.push(DrawingMutation::ImportImageAsset(crate::mutations::ImportImageAsset{asset_id:std::mem::take(&mut self.texts[0]),asset:self.asset.take().unwrap()}));self.phase=6;},
  6=>{self.mutations.push(DrawingMutation::CreateLayer(crate::mutations::CreateLayer{parent_id:input.parent_id.as_ref().map(|_|std::mem::take(&mut self.texts[5])),index:input.index.or_else(||input.parent_id.is_none().then_some(snapshot.layers.len())),layer:self.boxed_layer.take().unwrap()}));self.phase=7;},
  7..=9=>{let index=self.phase-7;if !self.string_fill{self.strings[index].try_reserve_exact(demand.capacity_bytes).map_err(|_|refused("image selection text admission failed"))?;receipt.retained_capacity_bytes=self.strings[index].capacity();self.string_fill=true;}else{let source=match index{0=>crate::editor::drawing::DRAWING_INTERACTION_DOMAIN,1=>crate::editor::drawing::DRAWING_INTERACTION_GRANULARITY,_=>std::str::from_utf8(&self.layer_id[..self.layer_length]).unwrap()};self.strings[index].push_str(source);self.string_fill=false;self.phase+=1;}},
  10=>{self.targets.try_reserve_exact(1).map_err(|_|refused("image selection target admission failed"))?;receipt.retained_capacity_bytes=self.targets.capacity()*size_of::<protocol::InteractionTarget>();self.phase=11;},
  11=>{self.targets.push(protocol::InteractionTarget{granularity:std::mem::take(&mut self.strings[1]),id:std::mem::take(&mut self.strings[2])});self.phase=12;},
  12=>{self.selection.try_reserve_exact(1).map_err(|_|refused("image selection backing admission failed"))?;receipt.retained_capacity_bytes=self.selection.capacity()*size_of::<InteractionWrite>();self.phase=13;},
  13=>{self.selection.push(InteractionWrite{domain:std::mem::take(&mut self.strings[0]),targets:std::mem::take(&mut self.targets),merge:protocol::MergeMode::Replace});self.phase=14;},
  _=>return Err(refused("image publication requires separate output handoff"))
 }if !receipt.fits(grant){return Err(refused("image publication allocation exceeded caller admission"));}Ok(receipt)}
 pub(crate) fn take_result(&mut self,input:&super::ImportImage,operation:&AppOperationContext,grant:RetainedCloneGrant)->Result<Option<(DrawingImagePublication,RetainedCloneProgress)>,ValueError>{if !self.ready(){return Err(refused("image publication is incomplete"));}let demand=self.work_demands(input,operation,grant.maximum_copy_bytes)?;if grant.maximum_items==0||grant.maximum_depth<1||grant.maximum_copy_bytes<demand.copy_bytes{return Ok(None);}self.phase=15;Ok(Some((DrawingImagePublication{mutations:std::mem::take(&mut self.mutations),selection:std::mem::take(&mut self.selection)},RetainedCloneProgress{copied_items:1,copied_bytes:demand.copy_bytes,..Default::default()})))}
}

